$schema=['@context'=>'https://schema.org','@graph'=>[['@type'=>'Article','headline'=>$a['title'],'description'=>$a['description'],'mainEntityOfPage'=>pramioUrl($slug),'datePublished'=>$date->format('Y-m-d'),'dateModified'=>$date->format('Y-m-d'),'inLanguage'=>'ru-RU','author'=>['@type'=>'Organization','name'=>'PRAMIO','url'=>'https://pramio.ru/'],'publisher'=>['@type'=>'Organization','name'=>'PRAMIO','url'=>'https://pramio.ru/']],['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Главная','item'=>'https://pramio.ru/'],['@type'=>'ListItem','position'=>2,'name'=>'Блог','item'=>'https://pramio.ru/blog/'],['@type'=>'ListItem','position'=>3,'name'=>'Тётя Лида знает','item'=>'https://pramio.ru/blog/tetya-lida/'],['@type'=>'ListItem','position'=>4,'name'=>(string)$a['title'],'item'=>pramioUrl($slug)]]]]];
$sj=json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
